const BASE = window.GRANTCURRENT_API_BASE || '/api/v1';
const TODAY = new Date('2026-10-17T12:00:00');

const state = {
  tab: localStorage.getItem('gc_v7_tab') || 'matching', role: localStorage.getItem('gc_role') || 'Administrator', theme: localStorage.getItem('gc_v7_theme') || 'light',
  loading: true, error: '',
  ops: [], selectedOpp: null, opQuery: 'Canadian funders for climate-resilient WASH in Malawi', opFilters: {recommendation:new Set(), gates:new Set(), relationship:new Set(), application:new Set(), freshness:new Set(), staff:new Set(), country:'ALL'},
  history: [], historyAll: [], historyOptions: {}, histAnalytics: null, histFilters: {year:'ALL',country:'ALL',theme:'ALL',funder_type:'ALL',relationship:'ALL',outcome:'ALL',q:''}, historySelected:null, pipelineMode:'history', historySort:{key:'submitted_date',dir:'desc'},
  funderProfiles: [], selectedFunder: null, funderMode:'profiles',
  gifts: [], giftQ:'', contacts: [], publicFunders: [],
  pipeline: [], decisions: [],
  userOpps: [], oppMode:'verified',
  projects: [], scenario:null,
  advisor:null, advisorQ:'What are the top five funding strategy recommendations?',
  outlier:false,
  report:null, pitch:false,
  countries:[], allCountries:[], planning:{}, scoring:{weights:{}}, trl:[], trlSource:'',
  providers:[], sources:[], roles:[], audit:[], issues:[], trlOrigin:'', trlNasa:'',
  pageMessage:''
};

const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = n => Number.isFinite(Number(n)) ? new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD',maximumFractionDigits:0}).format(Number(n)) : '—';
const pct = n => Number.isFinite(Number(n)) ? `${Number(n).toFixed(1)}%` : '—';
const num = n => Number.isFinite(Number(n)) ? new Intl.NumberFormat('en-CA',{maximumFractionDigits:1}).format(Number(n)) : '—';
const uniq = a => [...new Set((a||[]).filter(Boolean))].sort((a,b)=>String(a).localeCompare(String(b)));
const short = (s,n=180) => String(s||'').length>n ? String(s).slice(0,n).trim()+'…' : String(s||'');
const qs = obj => Object.entries(obj).filter(([,v])=>v && v!=='ALL').map(([k,v])=>`${encodeURIComponent(k)}=${encodeURIComponent(v)}`).join('&');

async function api(path, options={}) {
  const headers = {...(options.headers||{}), 'X-GrantCurrent-Role': state.role};
  if (options.body && !headers['Content-Type']) headers['Content-Type']='application/json';
  const r = await fetch(`${BASE}${path}`, {...options, headers});
  if (!r.ok) throw new Error((await r.text()) || `${r.status} ${r.statusText}`);
  const ct = r.headers.get('content-type')||'';
  return ct.includes('application/json') ? r.json() : r.text();
}

function icon(name){ const m={overview:'◫',pipeline:'▤',funders:'◆',matching:'◎',analytics:'▥',advisor:'✦',planner:'◈',reports:'▣',admin:'⚙'}; return m[name]||'•'; }
const NAV=[['overview','Overview'],['pipeline','Pipeline Explorer'],['funders','Funder Intelligence'],['matching','Opportunity Matching'],['analytics','Fundraising Analytics'],['advisor','FundScope Advisor'],['planner','Project Funding Planner'],['reports','Reports & Pitch Mode'],['admin','Administration']];

function appShell(content){
  document.documentElement.dataset.theme=state.theme;
  return `<div class="classicShell">
    <header class="classicHeader">
      <div class="classicTop">
        <div class="classicBrand">
          <div class="classicMark"><span></span><span></span></div>
          <div><b>GrantCurrent</b><small>Evidence-backed funding intelligence</small></div>
        </div>
        <div class="classicSearch"><input id="topSearch" value="${esc(state.opQuery)}" placeholder="Search Canadian funders, WaterAid countries, WASH themes or opportunities"/><button id="topSearchBtn">Search funding</button></div>
        <label class="roleSelect" title="Demo role; server-side permissions are enforced"><span>Role</span><select id="roleSelect">${['Administrator','Fundraising Manager','Analyst','Project Manager','Read-only Viewer'].map(x=>`<option ${state.role===x?'selected':''}>${x}</option>`).join('')}</select></label>
        <button id="themeToggle" class="iconBtn" title="Toggle theme">${state.theme==='light'?'☾':'☀'}</button>
      </div>
      <div class="classicNotice"><b>HACKATHON DEMO</b><span>Synthetic history ≠ WaterAid records</span><i>Canadian funders → configurable WaterAid countries</i><small>v0.7 Classic · humans decide</small></div>
      <nav class="classicNav">${NAV.map(([id,label])=>`<button class="${state.tab===id?'active':''}" data-nav="${id}"><span>${icon(id)}</span>${esc(label)}</button>`).join('')}</nav>
    </header>
    <main class="classicContent">${state.pageMessage?`<div class="toast">${esc(state.pageMessage)}</div>`:''}${content}</main>
  </div>`;
}

function pageHeader(kicker,title,sub,actions=''){return `<div class="pageHeader"><div><span class="kicker">${esc(kicker)}</span><h1>${title}</h1><p>${sub}</p></div><div class="pageActions">${actions}</div></div>`}
function syntheticBanner(){return `<div class="syntheticBanner"><b>Demo data notice</b><span>The historical pipeline is synthetic data from the fictional Water Care challenge. It is used to demonstrate analytics and must never be presented as WaterAid history.</span></div>`}
function kpi(label,value,sub='',tone='blue'){return `<article class="kpi ${tone}"><span>${esc(label)}</span><strong>${value}</strong><small>${esc(sub)}</small></article>`}
function pill(text,cls=''){return `<span class="pill ${cls}">${esc(text)}</span>`}
function decisionClass(x){return String(x||'').toLowerCase().replaceAll(' ','-').replaceAll('+','plus')}

function options(vals,current){return `<option value="ALL">All</option>${(vals||[]).map(x=>`<option value="${esc(x)}" ${current===x?'selected':''}>${esc(x)}</option>`).join('')}`}

function chartBars(items,{label='label',value='awarded_cad',format='money',maxItems=8}={}){
  const rows=(items||[]).slice(0,maxItems); const max=Math.max(1,...rows.map(x=>Number(x[value]||0)));
  return `<div class="barChart">${rows.map(x=>`<div class="barRow"><div class="barLabel"><b>${esc(x[label])}</b><small>n=${x.n??'—'}</small></div><div class="barTrack"><i style="width:${Math.max(1,Number(x[value]||0)/max*100)}%"></i></div><strong>${format==='money'?money(x[value]):format==='pct'?pct(x[value]):num(x[value])}</strong></div>`).join('')||'<div class="empty">No data for these filters.</div>'}</div>`
}

function overviewPage(){
  const a=state.histAnalytics||{metrics:{},groups:{}}; const m=a.metrics||{}; const groups=a.groups||{};
  const filters=`<div class="globalFilters"><label>Fiscal year<select data-hf="year">${options(state.historyOptions.year,state.histFilters.year)}</select></label><label>Country<select data-hf="country">${options(state.historyOptions.country,state.histFilters.country)}</select></label><label>WASH theme<select data-hf="theme">${options(state.historyOptions.theme,state.histFilters.theme)}</select></label><label>Funder type<select data-hf="funder_type">${options(state.historyOptions.funder_type,state.histFilters.funder_type)}</select></label><label>Relationship<select data-hf="relationship">${options(state.historyOptions.relationship,state.histFilters.relationship)}</select></label><label>Outcome<select data-hf="outcome">${options(state.historyOptions.outcome,state.histFilters.outcome)}</select></label><button class="ghost" id="resetHistFilters">Reset filters</button></div>`;
  return appShell(`${pageHeader('Executive intelligence','Funding intelligence at a glance','Use the synthetic pipeline to understand historical patterns, then use separately verified public evidence to decide what deserves attention now.',`<button class="secondary" data-nav="reports">Generate report</button>`)}${syntheticBanner()}${filters}
    <div class="kpiGrid five">${kpi('Applications',m.total_applications??'—','selected historical records')}${kpi('Requested',money(m.total_requested_cad),'CAD')}${kpi('Awarded',money(m.total_awarded_cad),'CAD','green')}${kpi('Unique funders',m.unique_funders??'—','synthetic history')}${kpi('Completed applications',m.completed_applications??'—','excludes Withdrawn + Not submitted')}${kpi('Fundraising hours',num(m.fundraising_hours),'historical effort','amber')}${kpi('Stage-success rate',pct(m.stage_success_rate),m.denominators?.stage_success_rate||'')}${kpi('Cash funding conversion',pct(m.funding_conversion_rate),m.denominators?.funding_conversion_rate||'','green')}${kpi('Awarded / hour',money(m.awarded_per_fundraising_hour),'historical ratio')}${kpi('Avg funded award',money(m.avg_award_per_funded_application),'positive awards only')}${kpi('Lost / ineligible effort',`${num(m.lost_application_effort_hours)} hrs`,'staff effort','amber')}</div>
    <div class="grid2"><section class="panel"><div class="panelHead"><h2>Requests vs awards by fiscal year</h2><span>All values recalculate with filters</span></div>${chartBars(groups.fiscal_year,{value:'requested_cad',maxItems:10})}<div class="legendLine"><i class="req"></i> Requested · awards are shown in the next chart</div></section><section class="panel"><div class="panelHead"><h2>Funding awarded by fiscal year</h2><span>CAD and sample size</span></div>${chartBars(groups.fiscal_year,{value:'awarded_cad',maxItems:10})}</section></div>
    <div class="grid3"><section class="panel"><div class="panelHead"><h2>Performance by donor type</h2></div>${chartBars(groups.funder_type,{value:'awarded_cad'})}</section><section class="panel"><div class="panelHead"><h2>Funding by WASH theme</h2></div>${chartBars(groups.theme,{value:'awarded_cad'})}</section><section class="panel"><div class="panelHead"><h2>Country distribution</h2></div>${chartBars(groups.country,{value:'awarded_cad'})}</section></div>
    <div class="grid2"><section class="panel"><div class="panelHead"><h2>Efficiency by application type</h2><span>Awarded CAD per fundraising hour</span></div>${chartBars(groups.application_type,{value:'awarded_per_hour',format:'money'})}</section><section class="panel"><div class="panelHead"><h2>Relationship strength</h2><span>Cash conversion rate</span></div>${chartBars(groups.relationship,{value:'cash_conversion_rate',format:'pct'})}</section></div>
    <section class="panel"><div class="panelHead"><h2>Application outcomes by year</h2><span>Won includes stage success even when award_cad = 0</span></div><div class="tableWrap"><table class="dataTable"><thead><tr><th>Fiscal year</th><th>Won</th><th>Lost</th><th>Ineligible</th><th>Withdrawn</th><th>Not submitted</th><th>Total</th></tr></thead><tbody>${(a.outcomes_by_year||[]).map(x=>`<tr><td><b>${esc(x.fiscal_year)}</b></td><td>${x.Won}</td><td>${x.Lost}</td><td>${x.Ineligible}</td><td>${x.Withdrawn}</td><td>${x['Not submitted']}</td><td>${x.total}</td></tr>`).join('')}</tbody></table></div></section>
    <div class="infoCallout"><b>Analytical safeguard</b><p>${esc(a.sample_warning||'Historical associations are descriptive, not causal or predictive.')}</p></div>`);
}

function historyFilterQuery(){return qs({...state.histFilters,q:state.histFilters.q});}
function historyTable(){
  let rows=[...state.history]; const {key,dir}=state.historySort; rows.sort((a,b)=>{let av=a[key]??'',bv=b[key]??'';if(['ask_cad','award_cad','fundraising_hours'].includes(key)){av=Number(av);bv=Number(bv)} return (av>bv?1:av<bv?-1:0)*(dir==='asc'?1:-1)});
  return `<div class="tableWrap"><table class="dataTable historyTable"><thead><tr>${[['record_id','ID'],['fiscal_year','Year'],['funder_name','Funder'],['application_type','Application'],['theme_code','Theme'],['country','Country'],['ask_cad','Ask'],['fundraising_hours','Hours'],['relationship_at_submission','Relationship'],['outcome','Outcome'],['award_cad','Award']].map(([k,l])=>`<th data-sort="${k}">${l}${key===k?(dir==='asc'?' ↑':' ↓'):''}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr data-hist="${esc(r.record_id)}" class="${state.historySelected?.record_id===r.record_id?'selected':''}"><td><b>${esc(r.record_id)}</b></td><td>${esc(r.fiscal_year)}</td><td><b>${esc(r.funder_name)}</b><small>${esc(r.funder_type)}</small></td><td>${esc(r.application_type)}</td><td>${esc(r.theme_code)}</td><td>${esc(r.country)}</td><td>${money(r.ask_cad)}</td><td>${num(r.fundraising_hours)}</td><td>${esc(r.relationship_at_submission)}</td><td>${pill(r.outcome,decisionClass(r.outcome))}</td><td>${money(r.award_cad)}</td></tr>`).join('')}</tbody></table></div>`;
}
function historyDetail(r){if(!r)return `<div class="detailEmpty">Select an application to inspect the exact historical record.</div>`;return `<aside class="recordDrawer"><button class="drawerClose" id="closeHistory">×</button><span class="kicker">Synthetic historical record</span><h2>${esc(r.funder_name)}</h2><p>${esc(r.record_id)} · ${esc(r.fiscal_year)} · ${esc(r.country)}</p><div class="detailFacts"><div><span>Application</span><b>${esc(r.application_type)}</b></div><div><span>Theme</span><b>${esc(r.theme_code)}</b></div><div><span>Ask</span><b>${money(r.ask_cad)}</b></div><div><span>Award</span><b>${money(r.award_cad)}</b></div><div><span>Fundraising effort</span><b>${num(r.fundraising_hours)} hrs</b></div><div><span>Relationship</span><b>${esc(r.relationship_at_submission)}</b></div><div><span>Outcome</span><b>${esc(r.outcome)}</b></div><div><span>Decision date</span><b>${esc(r.decision_date||'—')}</b></div></div><h3>Reason / note</h3><div class="noteBox">${esc(r.reason_or_note||'No note recorded. Blank notes are not interpreted as success or failure.')}</div><div class="syntheticMini">This record is fictional challenge data, not a WaterAid application.</div></aside>`}

function currentPipelineBoard(){const stages=['Qualified','Cultivating','Applying','Submitted','Won/Lost'];return `<div class="board">${stages.map(s=>`<section class="boardCol"><div class="boardHead"><b>${s}</b><span>${state.pipeline.filter(x=>x.stage===s).length}</span></div>${state.pipeline.filter(x=>x.stage===s).map(x=>`<article class="pipeCard"><b>${esc(x.funder)}</b><span>${esc(x.title)}</span><small>${esc(x.owner||'Unassigned')} · ${esc(x.deadline||'No deadline')}</small><p>${esc(x.next_action||'No next action')}</p><select data-pipe-stage="${x.id}">${stages.map(t=>`<option ${t===x.stage?'selected':''}>${t}</option>`).join('')}</select></article>`).join('')||'<div class="emptySmall">No items</div>'}</section>`).join('')}</div>`}

function pipelinePage(){const filters=`<div class="historyFilters"><input id="histQ" value="${esc(state.histFilters.q)}" placeholder="Search funder, country, note or record ID"/><select data-hf="year">${options(state.historyOptions.year,state.histFilters.year)}</select><select data-hf="country">${options(state.historyOptions.country,state.histFilters.country)}</select><select data-hf="theme">${options(state.historyOptions.theme,state.histFilters.theme)}</select><select data-hf="outcome">${options(state.historyOptions.outcome,state.histFilters.outcome)}</select><button class="ghost" id="applyHistSearch">Search</button></div>`;
return appShell(`${pageHeader('Historical pipeline explorer','See every application behind the analytics','Search, sort, validate and export the full synthetic L1 pipeline history. The current pursuit board is available as a second workspace.',`<button class="secondary" id="exportHistory">Export CSV</button>`)}${syntheticBanner()}<div class="subTabs"><button class="${state.pipelineMode==='history'?'active':''}" data-pipeline-mode="history">Historical applications <b>${state.history.length}</b></button><button class="${state.pipelineMode==='current'?'active':''}" data-pipeline-mode="current">Current pursuit board <b>${state.pipeline.length}</b></button></div>${state.pipelineMode==='history'?`${filters}<div class="uploadBar"><label class="fileBtn">Validate & import CSV<input type="file" id="historyUpload" accept=".csv,text/csv"/></label><span>Comment lines beginning with # are skipped; duplicate record IDs are not re-imported.</span><button class="ghost" id="benchmarkCheck">Check 104-record benchmarks</button></div><div class="splitDetail"><div>${historyTable()}</div>${historyDetail(state.historySelected)}</div>`:currentPipelineBoard()}`)};

function funderProfileCard(f){return `<article class="funderCard" data-funder="${esc(f.funder_id||f.funder_name)}"><div class="funderTitle"><div><span>${esc(f.funder_type)}</span><h3>${esc(f.funder_name)}</h3></div>${pill(f.historical_pattern,f.cash_conversion_rate>=50?'good':'neutral')}</div><div class="funderMetrics"><div><span>Applications</span><b>${f.application_count}</b></div><div><span>Stage success</span><b>${pct(f.stage_success_rate)}</b></div><div><span>Cash conversion</span><b>${pct(f.cash_conversion_rate)}</b></div><div><span>Awarded</span><b>${money(f.awarded_cad)}</b></div></div><p>${esc(f.ai_insight)}</p><small>Evidence confidence: ${esc(f.confidence)} · descriptive synthetic history only</small></article>`}
function funderInsight(f){if(!f)return '';return `<section class="panel insightPanel"><span class="kicker">AI Insight Panel · grounded deterministic analysis</span><h2>${esc(f.funder_name)}</h2><p class="bigInsight">${esc(f.ai_insight)}</p><div class="grid3 mini"><div><span>Countries historically submitted</span><b>${esc((f.countries||[]).join(', ')||'—')}</b></div><div><span>WASH themes</span><b>${esc((f.themes||[]).join(', ')||'—')}</b></div><div><span>Average fundraising effort</span><b>${num(f.avg_fundraising_hours)} hrs</b></div></div><h3>Reasons for unsuccessful applications</h3>${(f.unsuccessful_reasons||[]).map(x=>`<div class="reasonRow"><span>${esc(x.reason)}</span><b>${x.n}</b></div>`).join('')||'<p>No unsuccessful-reason evidence in the selected history.</p>'}<div class="infoCallout"><b>Guardrail</b><p>This insight does not infer current donor eligibility, open calls, deadlines or current priorities. Those require separately verified public evidence or manual entry.</p></div></section>`}
function giftExplorer(){const q=state.giftQ.toLowerCase();const rows=state.gifts.filter(g=>!q||Object.values(g).join(' ').toLowerCase().includes(q));return `<section class="panel"><div class="panelHead"><div><h2>Gift Explorer</h2><span>Observed public giving signals from Canadian funders</span></div></div><div class="searchRow"><input id="giftQ" value="${esc(state.giftQ)}" placeholder="Search gifts by funder, recipient, focus, country or keyword"/><button id="giftSearch" class="primary">Search</button></div><div class="tableWrap"><table class="dataTable"><thead><tr><th>Recipient</th><th>Funder</th><th>Amount</th><th>Focus</th><th>Location</th><th>Year</th><th>Description</th></tr></thead><tbody>${rows.map(g=>`<tr><td><b>${esc(g.recipient)}</b></td><td>${esc(g.funder)}</td><td>${money(g.amount_cad??g.amount)}</td><td>${esc(g.focus||g.theme)}</td><td>${esc(g.location||g.country)}</td><td>${esc(g.year)}</td><td>${esc(short(g.description||g.evidence,140))}${g.source_url?`<a href="${esc(g.source_url)}" target="_blank">source ↗</a>`:''}</td></tr>`).join('')}</tbody></table></div></section>`}
function contactsView(){return `<section class="panel"><div class="panelHead"><h2>Verified public outreach paths</h2><span>No invented personal contacts</span></div><div class="cardGrid">${state.contacts.map(c=>`<article class="simpleCard"><b>${esc(c.funder)}</b><span>${esc(c.role||c.contact_name||'Public contact')}</span><p>${esc(c.channel||c.contact||'')}</p>${c.source_url?`<a href="${esc(c.source_url)}" target="_blank">verify source ↗</a>`:''}</article>`).join('')}</div></section>`}
function fundersPage(){const selected=state.selectedFunder||state.funderProfiles[0];return appShell(`${pageHeader('Funder intelligence','Understand the donor before you spend proposal hours','Historical evidence explains past patterns. Verified public evidence is kept separate for current eligibility and access.')} ${syntheticBanner()}<div class="subTabs"><button class="${state.funderMode==='profiles'?'active':''}" data-funder-mode="profiles">Historical profiles</button><button class="${state.funderMode==='gifts'?'active':''}" data-funder-mode="gifts">Gift Explorer</button><button class="${state.funderMode==='contacts'?'active':''}" data-funder-mode="contacts">Public contacts</button></div>${state.funderMode==='profiles'?`<div class="funderLayout"><div class="funderList">${state.funderProfiles.map(funderProfileCard).join('')}</div>${funderInsight(selected)}</div>`:state.funderMode==='gifts'?giftExplorer():contactsView()}`)};

function gateSummary(o){const gs=o.gates||[];if(gs.some(g=>g.result==='Fail'))return 'fails';if(gs.some(g=>g.result==='Uncertain'))return 'uncertain';if(gs.length===8&&gs.every(g=>g.result==='Pass'))return 'pass';return 'uncertain'}
function freshnessSummary(o){const dates=(o.evidence||[]).map(e=>e.retrieved).filter(Boolean).map(x=>new Date(x+'T00:00:00'));if(!dates.length)return 'old';const newest=new Date(Math.max(...dates));const days=Math.round((TODAY-newest)/86400000);return days<=90?'fresh':'old'}
function staffSummary(o){const d=[...state.decisions].filter(x=>x.opportunity_id===o.opp_id).sort((a,b)=>(b.id||0)-(a.id||0))[0];if(!d)return 'not';return d.human_decision===d.system_decision?'agreed':'changed'}
function relSummary(o){return (o.relationship_path?.consent||'').toLowerCase()==='yes'?'linked':'cold'}
function appSummary(o){const a=o.money_effort?.application_type||'Not stated or not applicable';const allowed=['LOI','Short application','Full proposal','Corporate proposal','Government call'];return allowed.includes(a)?a:'Not stated or not applicable'}
function countBy(fn,val){return state.ops.filter(o=>fn(o)===val).length}
function checkboxGroup(title,key,rows){const set=state.opFilters[key];return `<div class="filterGroup"><h4>${title}</h4>${rows.map(([v,l,c])=>`<label><input type="checkbox" data-op-filter="${key}" value="${esc(v)}" ${set.has(v)?'checked':''}/><span>${esc(l)}</span><b>${c}</b></label>`).join('')}</div>`}
function requestedFilters(){
 const c={};['PURSUE','PURSUE-QUEUE','CULTIVATE','REVIEW','MONITOR','DECLINE'].forEach(x=>c[x]=state.ops.filter(o=>o.decision===x).length);
 const apps=['LOI','Short application','Full proposal','Corporate proposal','Government call','Not stated or not applicable'];
 return `<aside class="judgeFilters"><div class="filterTop"><h3>Filters</h3><button id="resetOppFilters">Reset</button></div>${checkboxGroup('Recommendation','recommendation',Object.keys(c).map(x=>[x,x,c[x]]))}${checkboxGroup('Hard gates','gates',[['pass','All 8 gates pass',countBy(gateSummary,'pass')],['uncertain','Uncertain on a gate',countBy(gateSummary,'uncertain')],['fails','Fails a gate',countBy(gateSummary,'fails')]])}${checkboxGroup('Relationship','relationship',[['linked','Linked person with consent',countBy(relSummary,'linked')],['cold','Cold, or no consent to approach',countBy(relSummary,'cold')]])}${checkboxGroup('Application type','application',apps.map(x=>[x,x,countBy(appSummary,x)]))}${checkboxGroup('Source freshness','freshness',[['fresh','Within 90 days',countBy(freshnessSummary,'fresh')],['old','Flagged: older than 90 days',countBy(freshnessSummary,'old')]])}${checkboxGroup('Staff decision','staff',[['not','Not reviewed',countBy(staffSummary,'not')],['agreed','Agreed with the tool',countBy(staffSummary,'agreed')],['changed','Changed by staff',countBy(staffSummary,'changed')]])}<div class="filterGroup"><h4>Target country</h4><select id="oppCountryFilter">${options(state.countries.map(x=>x.country),state.opFilters.country)}</select></div></aside>`;
}
function filteredVerifiedOps(){return state.ops.filter(o=>{
 const f=state.opFilters;if(f.recommendation.size&&!f.recommendation.has(o.decision))return false;if(f.gates.size&&!f.gates.has(gateSummary(o)))return false;if(f.relationship.size&&!f.relationship.has(relSummary(o)))return false;if(f.application.size&&!f.application.has(appSummary(o)))return false;if(f.freshness.size&&!f.freshness.has(freshnessSummary(o)))return false;if(f.staff.size&&!f.staff.has(staffSummary(o)))return false;if(f.country!=='ALL'&&!(o.target_countries||[]).includes(f.country))return false;return true;
})}
function oppTable(rows){return `<div class="tableWrap"><table class="dataTable oppTable"><thead><tr><th>Funder & program</th><th>Fit</th><th>Hard gates</th><th>Recommendation</th><th>Key date</th><th>Hours</th><th>Freshness</th></tr></thead><tbody>${rows.map(o=>`<tr data-opp="${esc(o.opp_id)}" class="${state.selectedOpp?.opp_id===o.opp_id?'selected':''}"><td><b>${esc(o.funder_name)}</b><small>${esc(o.title)}</small></td><td><b>${o.fit_score==null?'—':Number(o.fit_score).toFixed(1)}/5</b></td><td>${pill(gateSummary(o)==='pass'?'All 8 pass':gateSummary(o)==='fails'?'Fails a gate':'Uncertain',gateSummary(o))}</td><td>${pill(o.decision,decisionClass(o.decision))}</td><td>${esc(o.deadline||o.status||'Unknown')}</td><td>${o.money_effort?.fundraising_hours!=null?`${num(o.money_effort.fundraising_hours)} + ${num(o.money_effort.program_hours||0)}`:'—'}</td><td>${freshnessSummary(o)==='fresh'?pill('Within 90 days','good'):pill('Older than 90 days','warn')}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">No opportunities match these filters.</td></tr>'}</tbody></table></div>`}
function evidenceLink(url,label='source ↗'){return url?`<a href="${esc(url)}" target="_blank" rel="noreferrer">${label}</a>`:''}
function fullBrief(o){if(!o)return `<section class="panel detailEmpty"><h2>Select a verified opportunity</h2><p>The one-page briefing note will appear here with the full judging criteria.</p></section>`; const m=o.money_effort||{}, rel=o.relationship_path||{};return `<section class="brief panel" id="briefPrint"><div class="briefHead"><div><span class="kicker">Funding briefing note</span><h2>${esc(o.funder_name)}</h2><p>${esc(o.title)}</p><div class="metaPills">${pill(o.decision,decisionClass(o.decision))}${pill(`Fit ${o.fit_score?.toFixed?.(1)||o.fit_score||'—'}/5`)}${pill(`Confidence ${o.confidence}`)}${pill(`Readiness ${o.readiness_index}/100`)}</div><div class="fundingStageBar"><div><span>Funding stage / current status</span><b>${esc(o.status||o.decision||'Unknown')}</b></div><div><span>Technology readiness criterion</span><b>Not stated in loaded evidence</b><small>TRL is evaluated only when a funder or project explicitly uses it.</small></div></div></div><button class="secondary" id="printBrief">Print / Save PDF</button></div><div class="briefSection"><div class="sectionTitle"><h3>Why it fits</h3><span>Top rubric evidence · C1–C7</span></div><div class="reasonCards">${[...(o.fit_criteria||[])].sort((a,b)=>(b.score*b.weight)-(a.score*a.weight)).slice(0,3).map(c=>`<article><b>${esc(c.criterion_id)} · ${esc(c.name)}</b><strong>${c.score}/5</strong><p>${esc(c.explanation)}</p><small>${esc(c.theme_or_country||'')} · ${c.weight}% weight</small>${evidenceLink(c.evidence_url)}</article>`).join('')}</div><details><summary>View complete C1–C7 score breakdown</summary>${(o.fit_criteria||[]).map(c=>`<div class="detailRow"><b>${esc(c.criterion_id)} · ${esc(c.name)}</b><span>${c.score}/5 · ${c.weight}%</span><p>${esc(c.explanation)}</p>${evidenceLink(c.evidence_url)}</div>`).join('')}</details></div><div class="briefSection"><div class="sectionTitle"><h3>Eligibility check</h3><span>G1–G8 · every gate keeps its evidence</span></div><div class="tableWrap"><table class="gateTable"><thead><tr><th>Gate</th><th>Result</th><th>Reason</th><th>Evidence</th></tr></thead><tbody>${(o.gates||[]).map(g=>`<tr><td><b>${esc(g.gate_id)} · ${esc(g.name)}</b><small>${esc((g.passport_ids||[]).join(', '))}</small></td><td>${pill(g.result,g.result.toLowerCase())}</td><td>${esc(g.reason)}</td><td>${g.evidence_quote?`<q>${esc(short(g.evidence_quote,180))}</q><small>${esc(g.retrieved||'')}</small>${evidenceLink(g.source_url)}`:'Unknown — no evidence loaded'}</td></tr>`).join('')}</tbody></table></div></div><div class="grid2"><div class="briefSection"><div class="sectionTitle"><h3>Key dates</h3></div>${(o.key_dates||[]).map(d=>`<article class="dateCard"><div><b>${esc(d.label)}</b>${pill(d.status,d.status.toLowerCase())}</div><strong>${esc(d.date||'Unknown')}</strong><p>${esc(d.detail||'')}</p>${d.evidence_quote?`<q>${esc(short(d.evidence_quote,160))}</q>`:''}${evidenceLink(d.source_url)}<small>${d.retrieved?`Retrieved ${esc(d.retrieved)}`:''}</small></article>`).join('')}</div><div class="briefSection"><div class="sectionTitle"><h3>Money & effort</h3></div><div class="factGrid"><div><span>Grant range</span><b>${esc(m.grant_range||o.amount||'Unknown')}</b></div><div><span>Likely ask</span><b>${esc(m.likely_ask||'Not set')}</b></div><div><span>Application type</span><b>${esc(m.application_type||'Unknown')}</b></div><div><span>Fundraising hours</span><b>${m.fundraising_hours==null?'Unknown':num(m.fundraising_hours)}</b></div><div><span>Program hours</span><b>${m.program_hours==null?'Unknown':num(m.program_hours)}</b></div><div><span>Expected value</span><b>${m.expected_value_cad==null?'Unknown':money(m.expected_value_cad)}</b></div><div><span>Capacity remaining</span><b>${m.capacity_remaining_hours==null?'Unknown':`${num(m.capacity_remaining_hours)} hrs`}</b></div><div><span>Fits capacity?</span><b>${m.fits_remaining_hours==null?'Unknown':m.fits_remaining_hours?'Yes':'No'}</b></div></div><p class="assumption">${esc(m.expected_value_note||m.planning_basis||'Unknown values stay unknown rather than being invented.')}</p></div></div><div class="grid2"><div class="briefSection"><div class="sectionTitle"><h3>Relationship path</h3></div><div class="relationshipBox"><div><span>Status</span><b>${esc(rel.status||'Unknown')}</b></div><div><span>Strength</span><b>${esc(rel.strength||'Unknown')}</b></div><div><span>Consent</span><b>${esc(rel.consent||'Unknown')}</b></div><div><span>Person / channel</span><b>${esc(rel.people_or_channel||'No approved path')}</b></div><p><b>Suggested ask:</b> ${esc(rel.suggested_ask||'Verify an appropriate public or consented route.')}</p>${rel.evidence_quote?`<q>${esc(short(rel.evidence_quote,180))}</q>`:''}${evidenceLink(rel.source_url)}</div></div><div class="briefSection"><div class="sectionTitle"><h3>Risks & unknowns</h3></div><ul class="riskList">${(o.risks_unknowns||[]).map(r=>`<li>${esc(r)}</li>`).join('')||'<li>No explicit risks loaded; verify current eligibility before pursuit.</li>'}</ul></div></div><div class="briefSection"><div class="sectionTitle"><h3>Next step</h3></div><div class="nextAction"><strong>${esc(o.next_step?.action||o.strong_action||'Verify current evidence.')}</strong><span>Owner: ${esc(o.next_step?.owner||'Unassigned')} · Due: ${esc(o.next_step?.due_date||'Not set')}</span></div></div><div class="briefSection"><div class="sectionTitle"><h3>Sources</h3><span>Every loaded source with retrieval date</span></div><div class="sourceCards">${(o.evidence||[]).map(e=>`<article><span>${esc(e.source_type||'Public source')}</span><p>“${esc(short(e.quote,260))}”</p>${evidenceLink(e.url)}<small>Retrieved ${esc(e.retrieved||'Unknown')}</small></article>`).join('')}</div></div><div class="humanDecision"><div><b>Human decision</b><p>The tool recommends; a fundraiser decides.</p></div><button class="primary" data-agree="${esc(o.opp_id)}">Agree with ${esc(o.decision)}</button><select id="humanDecision">${['PURSUE','PURSUE-QUEUE','CULTIVATE','REVIEW','MONITOR','DECLINE'].map(x=>`<option ${x===o.decision?'selected':''}>${x}</option>`).join('')}</select><input id="decisionReason" placeholder="Reason if you change the recommendation"/><button class="secondary" data-record-decision="${esc(o.opp_id)}">Save decision</button></div></section>`}

function verifiedMatching(){const rows=filteredVerifiedOps();return `<div class="matchingLayout">${requestedFilters()}<div class="matchingMain"><div class="searchHero"><input id="oppSearch" value="${esc(state.opQuery)}"/><button class="primary" id="runOppSearch">Find funding</button></div>${oppTable(rows)}${fullBrief(state.selectedOpp||rows[0])}</div></div>`}
function userOpportunityForm(){return `<section class="panel"><div class="panelHead"><div><h2>Create & score a funding opportunity</h2><span>Transparent 0–100 prioritization · not a probability of award</span></div></div><form id="userOppForm" class="formGrid"><label>Proposed project name<input id="uoName" required/></label><label>Country<select id="uoCountry" required>${state.countries.map(c=>`<option>${esc(c.country)}</option>`).join('')}</select></label><label>WASH theme<input id="uoTheme" required placeholder="e.g. WASH-HCF, climate-resilient water"/></label><label>Target population / beneficiaries<input id="uoBeneficiaries" placeholder="e.g. 45,000 rural residents"/></label><label class="span2">Project description<textarea id="uoDescription"></textarea></label><label>Funding requirement (CAD)<input id="uoFunding" type="number" min="0" value="100000"/></label><label>Expected application effort (hours)<input id="uoEffort" type="number" min="0" value="24"/></label><label>Potential Canadian donor<input id="uoDonor" placeholder="Optional exact historical funder name"/></label><label>Current relationship<select id="uoRelationship"><option>Unknown</option><option>Cold</option><option>Warm</option><option>Active</option><option>Lapsed</option></select></label><label>Submission deadline<input id="uoDeadline" type="date"/></label><label>Funding stage<select id="uoStage"><option>Prospecting</option><option>Open call</option><option>LOI</option><option>Full proposal</option><option>Submitted</option><option>Awarded</option><option>Closed / declined</option></select></label><label>Technology Readiness Level (optional)<select id="uoTrl"><option value="">Not applicable / not stated</option>${state.trl.map(t=>`<option value="${t.trl}">TRL ${t.trl} — ${esc(t.name)}</option>`).join('')}</select><small>TRL measures technology maturity, not funding stage.</small></label><label class="span2">Eligibility requirements<textarea id="uoEligibility" placeholder="Paste or summarize verified eligibility requirements"></textarea></label><label class="span2">Evidence links / documents<textarea id="uoEvidence" placeholder="First-party URLs or document references"></textarea></label><div class="span2 formActions"><button class="primary" type="submit">Score opportunity</button></div></form></section><section class="panel"><div class="panelHead"><h2>Scored opportunities</h2><span>Eligibility Unverified overrides a preliminary fit score</span></div><div class="cardGrid">${state.userOpps.map(o=>`<article class="scoreCard"><div><b>${esc(o.project_name)}</b>${pill(o.priority,o.priority==='High'?'good':o.priority==='Eligibility Unverified'?'warn':'neutral')}</div><strong>${num(o.score)}/100</strong><p>${esc(o.country)} · ${esc(o.wash_theme)} · ${esc(o.funding_stage)}</p><small>${o.trl?`TRL ${o.trl} · `:''}${esc(o.eligibility_status)}</small><details><summary>Score breakdown & risks</summary>${Object.entries(o.score_breakdown||{}).map(([k,v])=>`<div class="detailRow"><b>${esc(k.replaceAll('_',' '))}</b><span>${num(v.score)}/100 · ${num(v.weight)}%</span><p>${esc(v.note||'')}</p></div>`).join('')}<ul>${(o.risks||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${(o.recommendations||[]).map(x=>`<p>${esc(x)}</p>`).join('')}</details><div class="cardActions"><button class="textBtn" data-edit-uo="${o.id}">Edit</button><button class="textBtn danger" data-delete-uo="${o.id}">Remove</button></div></article>`).join('')||'<div class="empty">No user-entered opportunities yet.</div>'}</div></section>`}
function matchingPage(){return appShell(`${pageHeader('Opportunity matching','Find funding, verify it, then decide whether it deserves attention','Verified public opportunities use the full briefing-note criteria. New opportunities can be entered and scored transparently.')}<div class="subTabs"><button class="${state.oppMode==='verified'?'active':''}" data-opp-mode="verified">Verified funding</button><button class="${state.oppMode==='new'?'active':''}" data-opp-mode="new">Score a new opportunity</button></div>${state.oppMode==='verified'?verifiedMatching():userOpportunityForm()}`)}

function analyticsPage(){const a=state.histAnalytics||{metrics:{},groups:{}};const m=a.metrics||{}, g=a.groups||{};return appShell(`${pageHeader('Fundraising analytics','Where does fundraising effort create the most value?','Use descriptive historical evidence with explicit sample sizes. Toggle the largest award out of efficiency comparisons so one outlier does not dominate.',`<label class="toggle"><input type="checkbox" id="outlierToggle" ${state.outlier?'checked':''}/><span>Exclude largest award from efficiency comparisons</span></label>`)}${syntheticBanner()}<div class="kpiGrid four">${kpi('Awarded / hour',money(m.awarded_per_fundraising_hour),'headline total')}${kpi('Hours / funded app',`${num(m.fundraising_hours_per_funded_application)} hrs`,'positive awards')}${kpi('Award-to-ask ratio',pct((m.award_to_ask_ratio||0)*100),'historical')}${kpi('Lost effort',`${num(m.lost_application_effort_hours)} hrs`,'Lost + Ineligible','amber')}</div>${a.outlier?.excluded?`<div class="infoCallout amber"><b>Outlier excluded from comparisons</b><p>${esc(a.outlier.record?.record_id||'Largest award')} · ${money(a.outlier.record?.award_cad)}. Headline totals remain unchanged.</p></div>`:''}<div class="grid2"><section class="panel"><div class="panelHead"><h2>Application type efficiency</h2><span>Awarded CAD per hour</span></div>${chartBars(g.application_type,{value:'awarded_per_hour',format:'money'})}</section><section class="panel"><div class="panelHead"><h2>Warm vs cold relationships</h2><span>Cash conversion · sample sizes shown</span></div>${chartBars(g.relationship,{value:'cash_conversion_rate',format:'pct'})}</section></div><div class="grid3"><section class="panel"><div class="panelHead"><h2>WASH themes</h2></div>${chartBars(g.theme,{value:'awarded_cad'})}</section><section class="panel"><div class="panelHead"><h2>Countries</h2></div>${chartBars(g.country,{value:'awarded_cad'})}</section><section class="panel"><div class="panelHead"><h2>Donor types</h2></div>${chartBars(g.funder_type,{value:'awarded_per_hour',format:'money'})}</section></div><div class="grid2"><section class="panel"><div class="panelHead"><h2>Donor concentration</h2><span>Share of historical awarded CAD</span></div>${(a.donor_concentration?.top_funders||[]).map(x=>`<div class="reasonRow"><span>${esc(x.funder)} <small>${pct(x.share_pct)} share</small></span><b>${money(x.awarded_cad)}</b></div>`).join('')}<p><b>Top funder share:</b> ${pct(a.donor_concentration?.top_1_share_pct||0)} · <b>Top five:</b> ${pct(a.donor_concentration?.top_5_share_pct||0)}</p></section><section class="panel"><div class="panelHead"><h2>High-effort unsuccessful applications</h2><span>Lost or Ineligible</span></div>${(a.high_effort_rejections||[]).slice(0,6).map(x=>`<div class="reasonRow"><span><b>${esc(x.record_id)}</b> ${esc(x.funder_name)} · ${esc(x.outcome)}</span><b>${num(x.fundraising_hours)} hrs</b></div>`).join('')}</section></div><div class="infoCallout"><b>Interpretation rule</b><p>${esc(a.sample_warning||'Small samples and outliers can distort percentages. These comparisons are associations, not proof of causation.')}</p></div>`)}

const SUGGESTED=['What explains our unsuccessful applications?','Which funder relationships should we strengthen?','Where are we investing too many fundraising hours?','Which WASH project themes perform best historically?','What are the top five funding strategy recommendations?','What changes if we exclude unusually large awards?','How should we prioritize our next grant applications?'];
function advisorPage(){const a=state.advisor;return appShell(`${pageHeader('FundScope Advisor','Ask the database, not a hallucination','The assistant uses deterministic grounded analysis of the actual imported history. It states assumptions and limitations instead of pretending a model knows more than the evidence.')} ${syntheticBanner()}<div class="advisorLayout"><aside class="suggestions"><h3>Suggested questions</h3>${SUGGESTED.map(q=>`<button data-advisor-q="${esc(q)}">${esc(q)}</button>`).join('')}</aside><section class="advisorPanel"><div class="chatInput"><textarea id="advisorQ">${esc(state.advisorQ)}</textarea><button class="primary" id="askAdvisor">Analyze</button></div>${a?`<div class="advisorAnswer"><span class="kicker">${esc(a.mode)}</span><h2>${esc(a.title)}</h2><ul>${(a.answer||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${a.supporting_record_ids?.length?`<p><b>Supporting records:</b> ${esc(a.supporting_record_ids.join(', '))}</p>`:''}<h3>Assumptions & limitations</h3>${(a.assumptions||[]).map(x=>`<div class="limitation">${esc(x)}</div>`).join('')}<small>Sample size: n=${a.sample_size}</small></div>`:`<div class="advisorEmpty">Choose a suggested question or ask your own question about the synthetic fundraising history.</div>`}</section></div>`)}

function projectCard(p){const pctFund=p.total_budget?Math.min(100,(p.existing_funding/p.total_budget)*100):0;return `<article class="projectCard"><div class="projectHead"><div><span>${esc(p.country)} · ${esc(p.priority)} priority</span><h3>${esc(p.title)}</h3></div>${p.trl?pill(`TRL ${p.trl}`):''}</div><p>${esc(p.intervention||'No intervention description')}</p><div class="fundTrack"><i style="width:${pctFund}%"></i></div><div class="fundNumbers"><span>${money(p.existing_funding)} secured</span><b>${money(p.funding_gap)} gap</b><span>${money(p.total_budget)} total</span></div><small>${esc(p.owner||'Unassigned')} · ${esc(p.readiness)} · ${esc(p.implementation_period||'Period not set')}</small><div class="linkedOpps"><b>Related opportunities</b>${(p.linked_opportunities||[]).map(id=>{const o=state.userOpps.find(x=>x.id===id);return o?`<span>${esc(o.project_name)} · ${esc(o.submission_deadline||'No deadline')}</span>`:`<span>Opportunity #${id}</span>`}).join('')||'<span>None linked yet</span>'}<select data-link-project="${p.id}"><option value="">Link a scored opportunity…</option>${state.userOpps.filter(o=>!(p.linked_opportunities||[]).includes(o.id)).map(o=>`<option value="${o.id}">${esc(o.project_name)}</option>`).join('')}</select></div><div class="cardActions"><button class="textBtn" data-edit-project="${p.id}">Edit</button><button class="textBtn danger" data-delete-project="${p.id}">Remove project</button></div></article>`}
function plannerPage(){return appShell(`${pageHeader('Project funding planner','Turn WASH needs into a fundable portfolio','Create real project concepts, track funding gaps, connect donor opportunities and scenario-test staff effort.')}<div class="plannerLayout"><section class="panel"><div class="panelHead"><h2>Create a WASH project</h2><span>Persists across refreshes</span></div><form id="projectForm" class="formGrid"><label>Project title<input id="prTitle" required/></label><label>Country<select id="prCountry">${state.countries.map(c=>`<option>${esc(c.country)}</option>`).join('')}</select></label><label>Community / location<input id="prCommunity"/></label><label>Beneficiary estimate<input id="prBeneficiaries" type="number" min="0"/></label><label class="span2">Water infrastructure / WASH intervention<textarea id="prIntervention"></textarea></label><label>Total project budget (CAD)<input id="prBudget" type="number" min="0" value="500000"/></label><label>Existing funding (CAD)<input id="prExisting" type="number" min="0" value="0"/></label><label>Implementation period<input id="prPeriod" placeholder="e.g. 2027–2029"/></label><label>Priority<select id="prPriority"><option>High</option><option selected>Medium</option><option>Low</option></select></label><label>Readiness<select id="prReadiness"><option>Concept</option><option selected>Planning</option><option>Ready for fundraising</option><option>Implementation</option></select></label><label>TRL (optional)<select id="prTrl"><option value="">Not applicable</option>${state.trl.map(t=>`<option value="${t.trl}">TRL ${t.trl} — ${esc(t.stage)}</option>`).join('')}</select></label><label>Fundraising owner<input id="prOwner"/></label><label class="span2">Milestones<textarea id="prMilestones"></textarea></label><div class="span2"><button class="primary" type="submit">Create project</button></div></form></section><section class="panel"><div class="panelHead"><h2>Funding scenario</h2><span>What if we pursue several grants at once?</span></div><label>Available staff hours<input id="scenarioHours" type="number" value="150" min="0"/></label><div class="scenarioChoices">${state.userOpps.map(o=>`<label><input type="checkbox" data-scenario-opp value="${o.id}"/> <span>${esc(o.project_name)} · ${num(o.expected_application_effort)} hrs · ${money(o.funding_requirement)}</span></label>`).join('')||'<p>Create scored opportunities first.</p>'}</div><button class="secondary" id="runScenario">Run scenario</button>${state.scenario?`<div class="scenarioResult"><b>${state.scenario.fits_staff_capacity?'Fits capacity':'Exceeds capacity'}</b><div>${kpi('Requested',money(state.scenario.total_requested_cad))}${kpi('Staff effort',`${num(state.scenario.staff_hours)} hrs`)}${kpi('Planning indicator',money(state.scenario.score_weighted_coverage_indicator_cad),'not guaranteed funding')}</div><p>${esc(state.scenario.warning)}</p></div>`:''}</section></div><div class="projectGrid">${state.projects.map(projectCard).join('')||'<div class="empty panel">No projects yet. Create one above.</div>'}</div>`)}

function reportCsv(report){const rows=[];const flat=(prefix,obj)=>{Object.entries(obj||{}).forEach(([k,v])=>{if(v&&typeof v==='object'&&!Array.isArray(v))flat(`${prefix}${k}.`,v);else rows.push([`${prefix}${k}`,Array.isArray(v)?JSON.stringify(v):v])})};flat('',report);return 'field,value\n'+rows.map(([a,b])=>`"${String(a).replaceAll('"','""')}","${String(b??'').replaceAll('"','""')}"`).join('\n')}
function reportContent(r){if(!r)return '<div class="empty panel">Report not loaded.</div>';return `<div class="reportDoc" id="reportPrint"><div class="reportCover"><span>GrantCurrent Executive Funding Strategy</span><h2>Canadian funders → global WaterAid WASH priorities</h2><p>Generated ${esc(r.generated_at)}</p><b>${esc(r.synthetic_notice)}</b></div><section><h3>1. Current fundraising position</h3><div class="factGrid">${Object.entries(r.current_position||{}).map(([k,v])=>`<div><span>${esc(k.replaceAll('_',' '))}</span><b>${typeof v==='number'?num(v):esc(v)}</b></div>`).join('')}</div></section><section><h3>2. Historical trends and constraints</h3>${Object.entries(r.historical_trends||{}).map(([k,v])=>`<p><b>${esc(k.replaceAll('_',' '))}:</b> ${typeof v==='number'?num(v):esc(v)}</p>`).join('')}</section><section><h3>3. Best-supported verified opportunities</h3>${(r.best_supported_opportunities||[]).map(x=>`<article class="reportRow"><b>${esc(x.funder)}</b><span>${esc(x.title)} · ${esc(x.decision)} · fit ${esc(x.fit)}</span></article>`).join('')||'<p>No verified pursue/queue opportunities loaded.</p>'}</section><section><h3>4–5. Efficiency problems & funding risks</h3><ul>${(r.risks||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><section><h3>6. Priority recommendations</h3><ol>${(r.priority_recommendations||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol></section><section><h3>7. 30 / 60 / 90-day action plan</h3><div class="grid3">${['30_days','60_days','90_days'].map(k=>`<article class="actionCard"><b>${k.replace('_days',' days')}</b>${(r.action_plan?.[k]||[]).map(x=>`<p>${esc(x)}</p>`).join('')}</article>`).join('')}</div></section></div>`}
function pitchMode(r){return `<div class="pitch"><section><span>Problem</span><h2>Scarce fundraiser time is being spent across disconnected grant research and application history.</h2></section><section><span>Evidence</span><h2>${num(r?.current_position?.historical_applications)} synthetic historical applications reveal effort, outcomes and donor patterns.</h2></section><section><span>Insights</span><h2>GrantCurrent separates stage success, cash conversion, eligibility evidence, fit and staff effort.</h2></section><section><span>Solution</span><h2>Canadian funder discovery → evidence → G1–G8 gates → fit → capacity → human decision.</h2></section><section><span>Priorities</span><h2>Fewer, better opportunities with visible unknowns and source freshness.</h2></section><section><span>Funding impact</span><h2>Projects track budget gaps while scenarios expose the staff hours needed to pursue funding.</h2></section><section><span>Next steps</span><h2>Verify current calls, calibrate decisions, expand public giving history and integrate organizational SSO/CRM.</h2></section></div>`}
function reportsPage(){return appShell(`${pageHeader('Reports & pitch mode','Turn evidence into an executive story','Generate a professional strategy summary using live application calculations. Demo assumptions and synthetic history stay clearly labelled.',`<button class="secondary" id="refreshReport">Refresh report</button><button class="secondary" id="exportReportCsv">Export CSV</button><button class="primary" id="printReport">Print / Save PDF</button>`)}<div class="subTabs"><button class="${!state.pitch?'active':''}" data-report-mode="report">Executive report</button><button class="${state.pitch?'active':''}" data-report-mode="pitch">Hackathon presentation mode</button></div>${state.pitch?pitchMode(state.report):reportContent(state.report)}`)}

function trlGuide(){return `<section class="panel"><div class="panelHead"><div><h2>Technology Readiness Levels (TRL)</h2><span>Innovation Canada / ISED · optional project criterion</span></div>${evidenceLink(state.trlSource,'Official source ↗')}</div><div class="infoCallout"><b>What TRL means</b><p>${esc(state.trlOrigin||'TRL 1–9 is a standardized technology-maturity framework.')}${state.trlNasa?` ${evidenceLink(state.trlNasa,'NASA history ↗')}`:''}</p><p><b>Important:</b> TRL measures technology maturity. It is not the administrative stage of a funding application and is not a probability of winning a grant. GrantCurrent records both separately.</p></div><div class="trlGrid">${state.trl.map(t=>`<article><strong>${t.trl}</strong><div><b>${esc(t.name)}</b><span>${esc(t.stage)}</span><p>${esc(t.description)}</p></div></article>`).join('')}</div></section>`}
function countriesAdmin(){return `<section class="panel"><div class="panelHead"><div><h2>Target countries</h2><span>Add, deactivate, edit or permanently remove countries without changing code</span></div></div><form id="addCountryForm" class="countryForm"><input id="newCountry" placeholder="Country" required/><input id="newRegion" placeholder="Region"/><input id="newCountrySource" placeholder="Source / note"/><input id="newCountryUrl" placeholder="Source URL"/><button class="primary">Add country</button></form><div class="tableWrap"><table class="dataTable"><thead><tr><th>Active</th><th>Country</th><th>Region</th><th>Source</th><th>Actions</th></tr></thead><tbody>${state.allCountries.map(c=>`<tr><td><input type="checkbox" data-country-active="${c.id}" ${c.active?'checked':''}/></td><td><b>${esc(c.country)}</b></td><td>${esc(c.region)}</td><td>${esc(c.source)}${c.source_url?evidenceLink(c.source_url):''}</td><td><button class="textBtn" data-edit-country="${c.id}">Edit</button><button class="textBtn danger" data-delete-country="${c.id}">Remove</button></td></tr>`).join('')}</tbody></table></div></section>`}
function scoringAdmin(){const w=state.scoring.weights||{};return `<section class="panel"><div class="panelHead"><div><h2>Opportunity scoring configuration</h2><span>Weights must total 100%</span></div><b>${num(Object.values(w).reduce((a,b)=>a+Number(b||0),0))}%</b></div><div class="formGrid scoringGrid">${Object.entries(w).map(([k,v])=>`<label>${esc(k.replaceAll('_',' '))}<input type="number" data-score-weight="${k}" value="${v}" min="0" max="100" step="1"/></label>`).join('')}<div class="span2"><button class="secondary" id="saveScoring">Save scoring weights</button></div></div></section>`}
function providerAdmin(){return `<section class="panel"><div class="panelHead"><div><h2>Sources & AI research</h2><span>Local RAG works without external keys</span></div></div><div class="providerGrid">${state.providers.map(p=>`<article><b>${esc(p.name)}</b>${pill(p.configured?'Ready':'Setup required',p.configured?'good':'warn')}<p>${esc(p.description||p.note||'')}</p></article>`).join('')}</div><details><summary>Public source register (${state.sources.length})</summary><div class="sourceList">${state.sources.map(s=>`<article><b>${esc(s.name||s.source)}</b><span>${esc(s.category||s.use_for||'')}</span>${evidenceLink(s.url||s.source_url)}</article>`).join('')}</div></details></section>`}
function planningAdmin(){return `<section class="panel"><div class="panelHead"><div><h2>Planning assumptions</h2><span>Challenge defaults are demo assumptions — replace them before operational use</span></div></div><div class="formGrid"><label>Remaining fundraising hours<input id="planHours" type="number" value="${state.planning.remaining_fundraising_hours??45}"/></label><label>Weekly brief limit<input id="planWeeklyLimit" type="number" value="${state.planning.weekly_review_limit??5}"/></label><label>Fundraising cost / hour<input id="planFundCost" type="number" value="${state.planning.blended_fundraising_cost??63}"/></label><label>Program cost / hour<input id="planProgramCost" type="number" value="${state.planning.program_cost??65}"/></label><label>Default win assumption<input id="planWin" type="number" step="0.01" min="0" max="1" value="${state.planning.default_win_probability??0.3}"/></label><label>Default owner<input id="planOwner" value="${esc(state.planning.default_owner||'Foundations Officer')}"/></label><label>Default internal due days<input id="planDue" type="number" value="${state.planning.default_due_days??14}"/></label><div class="span2"><button class="secondary" id="savePlanning">Save planning assumptions</button></div></div></section>`}
function auditAdmin(){return `<section class="panel"><div class="panelHead"><h2>Audit & data quality</h2><span>Recent application actions and reported data issues</span></div><div class="grid2"><div><h3>Recent audit log</h3><div class="auditList">${state.audit.slice(0,20).map(a=>`<article><b>${esc(a.action)} · ${esc(a.entity_type)}</b><span>${esc(a.role)} · ${esc(a.created_at)}</span></article>`).join('')||'<p>No audit events yet.</p>'}</div></div><div><h3>Data issues</h3><div class="issueForm"><input id="issuePage" placeholder="Page / opportunity ID"/><textarea id="issueDescription" placeholder="Describe the data issue or source conflict"></textarea><input id="issueSource" placeholder="Source URL (optional)"/><button class="secondary" id="createIssue">Report issue</button></div><div class="auditList">${state.issues.slice(0,20).map(i=>`<article><b>${esc(i.status)} · ${esc(i.page||i.opportunity_id||'General')}</b><span>${esc(i.description)}</span></article>`).join('')||'<p>No reported issues.</p>'}</div></div></div></section>`}
function adminPage(){return appShell(`${pageHeader('Administration','Scope, evidence, assumptions and access','Configure the target-country scope, scoring model, planning assumptions and research providers. The role selector is enforced server-side in this hackathon build; production should replace demo identity with organizational SSO.')}<div class="adminStack">${countriesAdmin()}${scoringAdmin()}${planningAdmin()}${trlGuide()}${providerAdmin()}${auditAdmin()}</div>`)}

function render(){
  if(state.loading){document.querySelector('#app').innerHTML='<div class="loadingScreen"><div class="spinner"></div><h1>Loading GrantCurrent</h1><p>Preparing funding intelligence…</p></div>';return}
  if(state.error){document.querySelector('#app').innerHTML=`<div class="fatal"><h1>GrantCurrent</h1><p>Could not load the API.</p><code>${esc(state.error)}</code><p>Open <b>http://localhost:8000/health</b> to confirm the backend is running.</p></div>`;return}
  const pages={overview:overviewPage,pipeline:pipelinePage,funders:fundersPage,matching:matchingPage,analytics:analyticsPage,advisor:advisorPage,planner:plannerPage,reports:reportsPage,admin:adminPage};
  document.querySelector('#app').innerHTML=(pages[state.tab]||overviewPage)(); bind();
}

async function loadHistory(){const q=historyFilterQuery();const [h,a]=await Promise.all([api(`/history${q?'?'+q:''}`),api(`/history/analytics${q?'?'+q:''}${q?'&':'?'}exclude_largest_award=${state.outlier}`)]);state.history=h.items;state.historyAll=h.items;state.historyOptions=h.filter_options;state.histAnalytics=a}
async function reloadOps(){state.ops=await api('/opportunities'); if(!state.selectedOpp||!state.ops.some(x=>x.opp_id===state.selectedOpp.opp_id))state.selectedOpp=state.ops.find(x=>x.decision==='PURSUE')||state.ops.find(x=>x.decision==='PURSUE-QUEUE')||state.ops[0]||null}
async function init(){
 try{
  const base=await Promise.all([api('/opportunities'),api('/gift-signals'),api('/contacts'),api('/pipeline'),api('/decisions'),api('/target-countries'),api('/planning-settings'),api('/providers'),api('/public-sources'),api('/funder-intelligence'),api('/user-opportunities'),api('/projects'),api('/executive-report'),api('/scoring-config'),api('/trl'),api('/roles'),api('/audit-logs'),api('/data-issues')]);
  [state.ops,{signals:state.gifts},{contacts:state.contacts},{items:state.pipeline},{items:state.decisions},state._targets,state.planning,{providers:state.providers},{sources:state.sources},state._fi,{items:state.userOpps},{items:state.projects},state.report,state.scoring,state._trl,state._roles,{items:state.audit},{items:state.issues}]=base;
  state.countries=state._targets.countries;state.allCountries=state._targets.all_countries;state.funderProfiles=state._fi.funders;state.trl=state._trl.levels;state.trlSource=state._trl.source_url;state.trlOrigin=state._trl.origin_note||'';state.trlNasa=state._trl.nasa_source_url||'';state.roles=state._roles.roles;state.publicFunders=(await api('/funders')).funders;
  state.selectedOpp=state.ops.find(x=>x.decision==='PURSUE')||state.ops.find(x=>x.decision==='PURSUE-QUEUE')||state.ops[0]||null; state.selectedFunder=state.funderProfiles[0]||null;
  await loadHistory();
 }catch(e){state.error=e.message||String(e)} finally{state.loading=false;render()}
}

async function runVerifiedSearch(q){state.pageMessage='Searching verified funding evidence…';render();try{const res=await api('/scan',{method:'POST',body:JSON.stringify({query:q,max_results:20})});state.ops=res.results;state.opQuery=q;state.selectedOpp=state.ops[0]||null;state.pageMessage=`Found ${state.ops.length} verified/ranked results.`}catch(e){alert(e.message);state.pageMessage=''}render()}
async function saveDecision(o,human,reason){const row=await api('/decisions',{method:'POST',body:JSON.stringify({opportunity_id:o.opp_id,system_decision:o.decision,human_decision:human,reason:reason||null})});state.decisions.unshift(row);state.pageMessage='Decision saved to the audit trail.';render()}

function bind(){
 document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.nav;localStorage.setItem('gc_v7_tab',state.tab);document.body.classList.remove('navOpen');render()});

 document.querySelector('.mobileMenu')?.addEventListener('click',()=>document.body.classList.toggle('navOpen'));
 const top=document.querySelector('#topSearch');document.querySelector('#topSearchBtn')?.addEventListener('click',()=>{state.tab='matching';state.oppMode='verified';runVerifiedSearch(top.value)});top?.addEventListener('keydown',e=>{if(e.key==='Enter'){state.tab='matching';runVerifiedSearch(top.value)}});
 document.querySelector('#roleSelect')?.addEventListener('change',e=>{state.role=e.target.value;localStorage.setItem('gc_role',state.role);state.pageMessage=`Demo role changed to ${state.role}.`;render()});
 document.querySelector('#themeToggle')?.addEventListener('click',()=>{state.theme=state.theme==='light'?'dark':'light';localStorage.setItem('gc_v7_theme',state.theme);render()});
 document.querySelectorAll('[data-hf]').forEach(s=>s.onchange=async e=>{state.histFilters[s.dataset.hf]=e.target.value;await loadHistory();render()});
 document.querySelector('#resetHistFilters')?.addEventListener('click',async()=>{state.histFilters={year:'ALL',country:'ALL',theme:'ALL',funder_type:'ALL',relationship:'ALL',outcome:'ALL',q:''};await loadHistory();render()});
 document.querySelectorAll('[data-pipeline-mode]').forEach(b=>b.onclick=()=>{state.pipelineMode=b.dataset.pipelineMode;render()});
 document.querySelector('#applyHistSearch')?.addEventListener('click',async()=>{state.histFilters.q=document.querySelector('#histQ').value;await loadHistory();render()});
 document.querySelectorAll('[data-sort]').forEach(th=>th.onclick=()=>{const k=th.dataset.sort;state.historySort={key:k,dir:state.historySort.key===k&&state.historySort.dir==='asc'?'desc':'asc'};render()});
 document.querySelectorAll('[data-hist]').forEach(r=>r.onclick=()=>{state.historySelected=state.history.find(x=>x.record_id===r.dataset.hist);render()});
 document.querySelector('#closeHistory')?.addEventListener('click',()=>{state.historySelected=null;render()});
 document.querySelector('#exportHistory')?.addEventListener('click',()=>{const q=historyFilterQuery();window.open(`${BASE}/history/export.csv${q?'?'+q:''}`,'_blank')});
 document.querySelector('#historyUpload')?.addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{const text=await f.text();const r=await api('/history/import',{method:'POST',body:JSON.stringify({csv_text:text})});alert(`Validation complete. Valid rows: ${r.valid_rows}. Inserted: ${r.inserted}. Duplicates skipped: ${r.duplicates}.\n${(r.warnings||[]).slice(0,8).join('\n')}`);await loadHistory();render()}catch(err){alert('CSV validation/import failed: '+err.message)}});
 document.querySelector('#benchmarkCheck')?.addEventListener('click',async()=>{const r=await api('/history/benchmarks');alert((r.pass?'All seeded benchmarks pass.':'Benchmark mismatch detected.')+'\n'+Object.entries(r.checks).map(([k,v])=>`${k}: ${v.actual} / expected ${v.expected} ${v.pass?'✓':'✕'}`).join('\n'))});
 document.querySelectorAll('[data-pipe-stage]').forEach(s=>s.onchange=async e=>{const id=Number(s.dataset.pipeStage);const row=await api(`/pipeline/${id}`,{method:'PATCH',body:JSON.stringify({stage:e.target.value})});state.pipeline=state.pipeline.map(x=>x.id===id?row:x);render()});
 document.querySelectorAll('[data-funder-mode]').forEach(b=>b.onclick=()=>{state.funderMode=b.dataset.funderMode;render()});
 document.querySelectorAll('[data-funder]').forEach(c=>c.onclick=()=>{state.selectedFunder=state.funderProfiles.find(f=>(f.funder_id||f.funder_name)===c.dataset.funder);render()});
 document.querySelector('#giftSearch')?.addEventListener('click',()=>{state.giftQ=document.querySelector('#giftQ').value;render()});
 document.querySelectorAll('[data-opp-mode]').forEach(b=>b.onclick=()=>{state.oppMode=b.dataset.oppMode;render()});
 document.querySelectorAll('[data-op-filter]').forEach(ch=>ch.onchange=e=>{const set=state.opFilters[ch.dataset.opFilter];e.target.checked?set.add(e.target.value):set.delete(e.target.value);render()});
 document.querySelector('#resetOppFilters')?.addEventListener('click',()=>{Object.keys(state.opFilters).forEach(k=>{if(state.opFilters[k] instanceof Set)state.opFilters[k].clear()});state.opFilters.country='ALL';render()});
 document.querySelector('#oppCountryFilter')?.addEventListener('change',e=>{state.opFilters.country=e.target.value;render()});
 document.querySelectorAll('[data-opp]').forEach(r=>r.onclick=()=>{state.selectedOpp=state.ops.find(x=>x.opp_id===r.dataset.opp);render()});
 document.querySelector('#runOppSearch')?.addEventListener('click',()=>runVerifiedSearch(document.querySelector('#oppSearch').value));
 document.querySelector('#printBrief')?.addEventListener('click',()=>window.print());
 document.querySelectorAll('[data-agree]').forEach(b=>b.onclick=()=>{const o=state.ops.find(x=>x.opp_id===b.dataset.agree);saveDecision(o,o.decision,'Accepted tool recommendation')});
 document.querySelectorAll('[data-record-decision]').forEach(b=>b.onclick=()=>{const o=state.ops.find(x=>x.opp_id===b.dataset.recordDecision);const h=document.querySelector('#humanDecision').value,r=document.querySelector('#decisionReason').value;if(h!==o.decision&&!r.trim())return alert('Please enter a reason when changing the recommendation.');saveDecision(o,h,r)});
 document.querySelector('#userOppForm')?.addEventListener('submit',async e=>{e.preventDefault();const body={project_name:document.querySelector('#uoName').value,country:document.querySelector('#uoCountry').value,wash_theme:document.querySelector('#uoTheme').value,beneficiaries:document.querySelector('#uoBeneficiaries').value,project_description:document.querySelector('#uoDescription').value,funding_requirement:Number(document.querySelector('#uoFunding').value||0),expected_application_effort:Number(document.querySelector('#uoEffort').value||0),potential_donor:document.querySelector('#uoDonor').value||null,relationship_status:document.querySelector('#uoRelationship').value,eligibility_requirements:document.querySelector('#uoEligibility').value||null,submission_deadline:document.querySelector('#uoDeadline').value||null,evidence_links:document.querySelector('#uoEvidence').value||null,trl:document.querySelector('#uoTrl').value?Number(document.querySelector('#uoTrl').value):null,funding_stage:document.querySelector('#uoStage').value};try{const row=await api('/user-opportunities',{method:'POST',body:JSON.stringify(body)});state.userOpps.unshift(row);state.pageMessage=`Opportunity scored ${row.score}/100 — ${row.priority}.`;render()}catch(err){alert(err.message)}});
 document.querySelectorAll('[data-edit-uo]').forEach(b=>b.onclick=async()=>{const id=Number(b.dataset.editUo),o=state.userOpps.find(x=>x.id===id);if(!o)return;const funding=prompt('Funding requirement (CAD)',o.funding_requirement)??o.funding_requirement;const effort=prompt('Expected application effort (hours)',o.expected_application_effort)??o.expected_application_effort;const stage=prompt('Funding stage',o.funding_stage)??o.funding_stage;const eligibility=prompt('Eligibility requirements',o.eligibility_requirements||'')??o.eligibility_requirements;const evidence=prompt('Evidence links / document references',o.evidence_links||'')??o.evidence_links;try{const row=await api(`/user-opportunities/${id}`,{method:'PATCH',body:JSON.stringify({funding_requirement:Number(funding),expected_application_effort:Number(effort),funding_stage:stage,eligibility_requirements:eligibility,evidence_links:evidence})});state.userOpps=state.userOpps.map(x=>x.id===id?row:x);render()}catch(err){alert(err.message)}});
 document.querySelectorAll('[data-delete-uo]').forEach(b=>b.onclick=async()=>{if(!confirm('Remove this scored opportunity?'))return;await api(`/user-opportunities/${b.dataset.deleteUo}`,{method:'DELETE'});state.userOpps=state.userOpps.filter(x=>x.id!==Number(b.dataset.deleteUo));render()});
 document.querySelector('#outlierToggle')?.addEventListener('change',async e=>{state.outlier=e.target.checked;await loadHistory();render()});
 document.querySelectorAll('[data-advisor-q]').forEach(b=>b.onclick=async()=>{state.advisorQ=b.dataset.advisorQ;state.advisor=await api('/advisor',{method:'POST',body:JSON.stringify({question:state.advisorQ,exclude_largest_award:state.outlier})});render()});
 document.querySelector('#askAdvisor')?.addEventListener('click',async()=>{state.advisorQ=document.querySelector('#advisorQ').value;state.advisor=await api('/advisor',{method:'POST',body:JSON.stringify({question:state.advisorQ,exclude_largest_award:state.outlier})});render()});
 document.querySelector('#projectForm')?.addEventListener('submit',async e=>{e.preventDefault();const body={title:document.querySelector('#prTitle').value,country:document.querySelector('#prCountry').value,community:document.querySelector('#prCommunity').value||null,beneficiaries:Number(document.querySelector('#prBeneficiaries').value||0),intervention:document.querySelector('#prIntervention').value||null,total_budget:Number(document.querySelector('#prBudget').value||0),existing_funding:Number(document.querySelector('#prExisting').value||0),implementation_period:document.querySelector('#prPeriod').value||null,priority:document.querySelector('#prPriority').value,readiness:document.querySelector('#prReadiness').value,trl:document.querySelector('#prTrl').value?Number(document.querySelector('#prTrl').value):null,owner:document.querySelector('#prOwner').value||null,milestones:document.querySelector('#prMilestones').value||null};try{const row=await api('/projects',{method:'POST',body:JSON.stringify(body)});state.projects.unshift(row);render()}catch(err){alert(err.message)}});
 document.querySelectorAll('[data-edit-project]').forEach(b=>b.onclick=async()=>{const id=Number(b.dataset.editProject),p=state.projects.find(x=>x.id===id);if(!p)return;const budget=prompt('Total project budget (CAD)',p.total_budget)??p.total_budget;const existing=prompt('Existing funding (CAD)',p.existing_funding)??p.existing_funding;const readiness=prompt('Readiness',p.readiness||'Planning')??p.readiness;const owner=prompt('Owner',p.owner||'')??p.owner;try{const row=await api(`/projects/${id}`,{method:'PATCH',body:JSON.stringify({total_budget:Number(budget),existing_funding:Number(existing),readiness,owner})});state.projects=state.projects.map(x=>x.id===id?row:x);render()}catch(err){alert(err.message)}});
 document.querySelectorAll('[data-link-project]').forEach(s=>s.onchange=async e=>{if(!e.target.value)return;try{await api('/project-funding-links',{method:'POST',body:JSON.stringify({project_id:Number(s.dataset.linkProject),opportunity_id:Number(e.target.value)})});state.projects=(await api('/projects')).items;render()}catch(err){alert(err.message)}});
 document.querySelectorAll('[data-delete-project]').forEach(b=>b.onclick=async()=>{if(!confirm('Remove this project?'))return;await api(`/projects/${b.dataset.deleteProject}`,{method:'DELETE'});state.projects=state.projects.filter(x=>x.id!==Number(b.dataset.deleteProject));render()});
 document.querySelector('#runScenario')?.addEventListener('click',async()=>{const ids=[...document.querySelectorAll('[data-scenario-opp]:checked')].map(x=>Number(x.value));state.scenario=await api('/scenario',{method:'POST',body:JSON.stringify({opportunity_ids:ids,staff_hour_limit:Number(document.querySelector('#scenarioHours').value||0)})});render()});
 document.querySelector('#refreshReport')?.addEventListener('click',async()=>{state.report=await api('/executive-report');render()});
 document.querySelector('#printReport')?.addEventListener('click',()=>window.print());
 document.querySelector('#exportReportCsv')?.addEventListener('click',()=>{const blob=new Blob([reportCsv(state.report)],{type:'text/csv'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='GrantCurrent_Executive_Report.csv';a.click();URL.revokeObjectURL(a.href)});
 document.querySelectorAll('[data-report-mode]').forEach(b=>b.onclick=()=>{state.pitch=b.dataset.reportMode==='pitch';render()});
 document.querySelector('#addCountryForm')?.addEventListener('submit',async e=>{e.preventDefault();try{await api('/target-countries',{method:'POST',body:JSON.stringify({country:document.querySelector('#newCountry').value,region:document.querySelector('#newRegion').value||'Other',source:document.querySelector('#newCountrySource').value||'User configured',source_url:document.querySelector('#newCountryUrl').value||null,active:true})});const r=await api('/target-countries');state.countries=r.countries;state.allCountries=r.all_countries;await reloadOps();render()}catch(err){alert(err.message)}});
 document.querySelectorAll('[data-country-active]').forEach(ch=>ch.onchange=async e=>{await api(`/target-countries/${ch.dataset.countryActive}`,{method:'PATCH',body:JSON.stringify({active:e.target.checked})});const r=await api('/target-countries');state.countries=r.countries;state.allCountries=r.all_countries;await reloadOps();render()});
 document.querySelectorAll('[data-edit-country]').forEach(b=>b.onclick=async()=>{const c=state.allCountries.find(x=>x.id===Number(b.dataset.editCountry));const country=prompt('Country',c.country);if(country===null)return;const region=prompt('Region',c.region);await api(`/target-countries/${c.id}`,{method:'PATCH',body:JSON.stringify({country,region})});const r=await api('/target-countries');state.countries=r.countries;state.allCountries=r.all_countries;render()});
 document.querySelectorAll('[data-delete-country]').forEach(b=>b.onclick=async()=>{if(!confirm('Permanently remove this country from the configured scope? You can add it again later.'))return;await api(`/target-countries/${b.dataset.deleteCountry}`,{method:'DELETE'});const r=await api('/target-countries');state.countries=r.countries;state.allCountries=r.all_countries;await reloadOps();render()});
 document.querySelector('#saveScoring')?.addEventListener('click',async()=>{const weights={};document.querySelectorAll('[data-score-weight]').forEach(i=>weights[i.dataset.scoreWeight]=Number(i.value));try{state.scoring=await api('/scoring-config',{method:'PATCH',body:JSON.stringify({weights})});render()}catch(e){alert(e.message)}});
 document.querySelector('#savePlanning')?.addEventListener('click',async()=>{state.planning=await api('/planning-settings',{method:'PATCH',body:JSON.stringify({remaining_fundraising_hours:Number(document.querySelector('#planHours').value),weekly_review_limit:Number(document.querySelector('#planWeeklyLimit').value),blended_fundraising_cost:Number(document.querySelector('#planFundCost').value),program_cost:Number(document.querySelector('#planProgramCost').value),default_win_probability:Number(document.querySelector('#planWin').value),default_owner:document.querySelector('#planOwner').value,default_due_days:Number(document.querySelector('#planDue').value)})});await reloadOps();render()});
 document.querySelector('#createIssue')?.addEventListener('click',async()=>{const description=document.querySelector('#issueDescription').value.trim();if(!description)return alert('Please describe the issue.');const page=document.querySelector('#issuePage').value.trim()||state.tab;const source_url=document.querySelector('#issueSource').value.trim()||null;const row=await api('/data-issues',{method:'POST',body:JSON.stringify({page,description,source_url})});state.issues.unshift(row);render()});
}

init();
